const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(eeObj) {
    return new Promise((resolve, reject) => {
      eeObj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  const region = ee.Geometry.Point([-122.3321, 47.6062]).buffer(15000);
  const scale = 5000;

  async function analyzeYear(year) {
    const start = ee.Date.fromYMD(year, 9, 1);
    const end = ee.Date.fromYMD(year, 12, 1); // exclusive
    // Primary: CHIRPS
    let source = 'CHIRPS';
    let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, end)
      .filterBounds(region)
      .select(['precipitation']);
    let n = await getInfoAsync(col.size());
    if (n === 0) {
      // Fallback: ERA5-Land daily aggregated
      source = 'ERA5-LAND';
      col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(start, end)
        .filterBounds(region)
        .select(['total_precipitation_sum'])
        .map(img => img.select('total_precipitation_sum').multiply(1000).rename('precipitation'));
      n = await getInfoAsync(col.size());
      if (n === 0) {
        return { code: 'C1' };
      }
    }
    const sumImg = col.sum(); // mm over period
    const countDict = await getInfoAsync(sumImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    const px = countDict ? countDict['precipitation'] : null;
    if (!px || px === 0) return { code: 'C2' };

    const meanDict = await getInfoAsync(sumImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    const totalMm = meanDict ? meanDict['precipitation'] : null;
    if (totalMm === null || !isFinite(totalMm) || totalMm < 0) return { code: 'C3' };

    return { code: 'OK', images: n, pixels: px, totalMm: totalMm, source: source };
  }

  try {
    console.log('Region: Seattle (15 km buffer). Scale: 5000 m');
    console.log('Clouds: N/A for precipitation datasets');

    const y2019 = await analyzeYear(2019);
    if (y2019.code !== 'OK') { console.log(`2019: ${y2019.code}`); console.log(y2019.code); return; }
    console.log(`2019: images=${y2019.images}, valid_px=${y2019.pixels}, total=${y2019.totalMm.toFixed(1)} mm [${y2019.source}]`);

    const y2020 = await analyzeYear(2020);
    if (y2020.code !== 'OK') { console.log(`2020: ${y2020.code}`); console.log(y2020.code); return; }
    console.log(`2020: images=${y2020.images}, valid_px=${y2020.pixels}, total=${y2020.totalMm.toFixed(1)} mm [${y2020.source}]`);

    const y2021 = await analyzeYear(2021);
    if (y2021.code !== 'OK') { console.log(`2021: ${y2021.code}`); console.log(y2021.code); return; }
    console.log(`2021: images=${y2021.images}, valid_px=${y2021.pixels}, total=${y2021.totalMm.toFixed(1)} mm [${y2021.source}]`);

    const cond = (y2021.totalMm > y2020.totalMm) && (y2021.totalMm > y2019.totalMm);
    console.log(`Check: 2021 > 2020 and 2019? ${cond ? 'true' : 'false'}`);
    console.log(cond ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
